5084	function Get-ClaudeInitProblem {
5085	    param($Events, [string]$Auth = 'subscription')
5086	    $r = [pscustomobject]@{ Problem = ''; Class = '' }
5087	    if ([int]$Events.InitCount -le 0) { return $r }
5088	    $lack = @(@(Get-PropertyValue $Events 'InitLacks' @()) | Where-Object { $_ }) | Select-Object -First 1
5089	    if ($null -ne $lack) { $r.Problem = "init event lacks $lack - the CLI's schema changed; pin the version"; $r.Class = 'capability'; return $r }
5090	    $extra = @(@($Events.InitTools) | Where-Object { $script:ClaudeTools -cnotcontains [string]$_ })
5091	    if ($extra.Count -gt 0) { $r.Problem = "the init event lists tools outside $($script:ClaudeTools -join ', '): $($extra -join ', ') - the turn's read-only capability is not proven"; $r.Class = 'permission'; return $r }
5092	    if (@($Events.InitMcp).Count -gt 0) { $r.Problem = "the init event lists MCP server(s) ($(@($Events.InitMcp) -join ', ')) - a reviewer runs without any"; $r.Class = 'permission'; return $r }
5093	    $badMode = @(@($Events.InitModes) | Where-Object { [string]$_ -cne $script:ClaudePermissionMode }) | Select-Object -First 1
5094	    if ($null -ne $badMode) { $r.Problem = "the init event names the permission mode '$(ConvertTo-ClaudeToken ([string]$badMode))', not $($script:ClaudePermissionMode)"; $r.Class = 'permission'; return $r }
5095	    if ($Auth -eq 'endpoint') {
5096	        if (@(@($Events.InitKeySources) | Where-Object { [string]$_ -ceq 'ANTHROPIC_API_KEY' }).Count -gt 0) {
5097	            $r.Problem = 'the init event names apiKeySource ANTHROPIC_API_KEY on an endpoint route - a competing credential reached the child (auth endpoint sends ANTHROPIC_AUTH_TOKEN only)'
5098	            $r.Class = 'auth'
5099	        }
5100	        return $r
5101	    }
5102	    $want = $(if ($Auth -eq 'api-key') { 'ANTHROPIC_API_KEY' } else { 'none' })
5103	    $badKey = @(@($Events.InitKeySources) | Where-Object { [string]$_ -cne $want }) | Select-Object -First 1
5104	    if ($null -ne $badKey) {
5105	        $shown = $(if ([string]$badKey) { ConvertTo-ClaudeToken ([string]$badKey) } else { '(none named)' })
5106	        $r.Problem = "the init event names apiKeySource $shown, not $want - the turn did not bill $(if ($Auth -eq 'api-key') { 'the API key' } else { 'the claude.ai subscription' }) the roster names (auth $Auth)"
5107	        $r.Class = 'auth'
5108	        return $r
5109	    }
5110	    return $r
5111	}
5112	
5113	# (wave 29b, E12, E13) What a turn's events prove about its MODEL against the pin ($Pinned: the id
5114	# or alias the turn asked for; -Exact: an endpoint route, equality only): every init event's model
5115	# must be the pinned one (D4: an alias takes an id of its family) - "model drift: asked <p>, served
5116	# <m>" -, and (E13) every assistant event's message.model must be the init's id after the [1m]
5117	# strip - "a different model authored an assistant message: <id>" (the largest-output heuristic of
5118	# modelUsage does not prove who answered). Class capability. { Problem ('' when proven or when
5119	# there is no init model); Class }. Run on every turn, a killed one included (E12).
5120	function Get-ClaudeServedModelProblem {
5121	    param($Events, [string]$Pinned = '', [switch]$Exact)
5122	    $r = [pscustomobject]@{ Problem = ''; Class = '' }
5123	    $served = [string]$Events.InitModel
5124	    if (-not $served) { return $r }
5125	    if ($Pinned) {
5126	        $drift = @(@($Events.InitModels) | Where-Object { -not (Test-ClaudeModelMatch -Pinned $Pinned -Served ([string]$_) -Exact:$Exact) }) | Select-Object -First 1
5127	        if ($null -ne $drift) { $r.Problem = "model drift: asked $Pinned, served $drift"; $r.Class = 'capability'; return $r }
5128	    }
5129	    $foreign = @(@($Events.AssistantModels) | Where-Object { -not (Test-ClaudeModelMatch -Pinned $served -Served ([string]$_) -Exact) }) | Select-Object -First 1
5130	    if ($null -ne $foreign) { $r.Problem = "a different model authored an assistant message: $foreign"; $r.Class = 'capability'; return $r }
5131	    return $r
5132	}
5133	
5134	# (item 3, D6) The wording of a usage limit and of a missing sign-in in claude's result text or
5135	# stderr ("Not logged in <middle dot> Please run /login" - obs; "... usage limit reached|<unix time>", "You've
5136	# hit your limit <middle dot> resets ...") - field names and wordings beyond the observed ones are assumed.
5137	# (wave 29b, E4) an endpoint route's 401/403 (P11: "Failed to authenticate. API Error: 401 ...") is
5138	# class auth; a 429 is class quota by its status (\b429\b) whatever its wording - extend the lists
5139	# after the first sightings of each provider's texts.
5140	$script:ClaudeQuotaRe = '(?i)usage limit|limit reached|hit your (?:usage |session |weekly )?limit|rate[ _]limit|weekly limit|session limit|quota|too many requests|\b429\b|credit balance is too low|overage'
5141	$script:ClaudeAuthRe = '(?i)not logged in|please run /login|invalid api key|oauth token (?:has )?(?:expired|revoked)|authentication[ _]error|failed to authenticate|api error: 40[13]\b|\b401\b|unauthori[sz]ed'
5142	
5143	# The failure rules of one claude turn (the main turn, a denial retry, a format repair, a timeout
5144	# continuation) - the adapter contract of agy and muse plus -Turn (the turn's options: Mode, Thread,
5145	# NewThread, Model, Auth) and the fields ModelResolved, OtherModels, ProofProblem and QuotaMark:
5146	#   $Pre             a failure the bridge already knows (timeout, could not start) - it wins over
5147	#                    everything but the proof of the turn's init and model (wave 29b, E12): a killed
5148	#                    turn whose init or model proof fails is FAILED with that problem and its class
5149	#                    ("<problem> (the turn was also stopped: <Pre>)"), ProofProblem set - the caller
5150	#                    runs no continuation on that session; otherwise a rejecting rate_limit_event
5151	#                    before the kill makes the class quota (no continuation)
5152	#   init proof       (item 4, item 6; evidence first, whatever the exit code) (E14) the capability
5153	#                    fields present -> else class capability; tools, MCP servers, permission mode ->
5154	#                    class permission; apiKeySource -> class auth; ProofProblem
5155	#   exit != 0        failed: claude exit <n> - <result text | stderr>; quota or auth wording -> that
5156	#                    class
5157	#   malformed        class transport; no init event (exit 0) -> class permission (not proven); no
5158	#                    result -> failed (the init's session id is a candidate)
5159	#   the session      init and result must agree; a new thread must come back on the minted id, a
5160	#                    resume (every secondary turn) on its thread, a fork on a NEW uuid (not its
5161	#                    parent) - else class unknown, the id a candidate only
5162	#   is_error / subtype other than success -> failed: claude <subtype> - <text>; class quota (a
5163	#                    rejecting rate_limit_event or the limit wording - D6), auth (its wording),
5164	#                    capability (error_max_turns - D8 -, error_max_structured_output_retries)
5165	#   the model        (D4) the init model must be the pinned one (an alias: an id of its family);
5166	#                    (E13) every assistant event's message.model must be the init's id after the
5167	#                    [1m] strip ("a different model authored an assistant message: <id>");
5168	#                    modelUsage's main model must be it too - else class capability, ProofProblem; a
5169	#                    modelUsage key that authored no assistant message is recorded (OtherModels) and
5170	#                    warned about (a helper model of the CLI)
5171	#   empty reply      with permission denials: failed, class permission, DeniedEmpty (the denial
5172	#                    retry); otherwise failed: empty reply
5173	#   usable           denials beside the reply (the tools and paths), a warning rate-limit status and
5174	#                    other models become Warnings; (E15) a REJECTING rate_limit_event during a turn
5175	#                    whose result succeeded keeps the reply usable: the warning "a rate limit
5176	#                    rejected a request during the turn: <the event's info, raw>" and QuotaMark (the
5177	#                    quota text a failed turn would carry - the caller marks the route's health with
5178	#                    it, New-ProviderFailure -Class quota)
5179	function Get-ClaudeTurnOutcome {
5180	    param($Events, [int]$ExitCode, [string]$StderrText = '', [string]$Pre = '', [string]$ExpectThread = '', [string]$ExpectModel = '', $Turn = $null)
5181	    $o = [pscustomobject]@{ Ok = $false; Outcome = ''; Class = ''; Texts = [string[]]@(); Thread = ''; ThreadCandidate = ''; Reply = ''; Structured = $false; DeniedEmpty = $false; DenialLine = ''; Permission = ''; NotFound = ''; Warnings = [string[]]@(); ModelResolved = ''; OtherModels = [string[]]@(); ProofProblem = ''; QuotaMark = '' }
5182	    $lines = @(([string]$StderrText) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
5183	    $stderrTail = $(if ($lines.Count -gt 0) { [string]$lines[-1] } else { '' })
5184	    $mode = [string](Get-PropertyValue $Turn 'Mode' '')
5185	    $turnThread = [string](Get-PropertyValue $Turn 'Thread' '')
5186	    $newThread = [string](Get-PropertyValue $Turn 'NewThread' '')
5187	    $auth = [string](Get-PropertyValue $Turn 'Auth' '')
5188	    if ($script:ClaudeAuthModes -notcontains $auth) { $auth = 'subscription' }
5189	    # (wave 29b, E2) an endpoint route's model is proven by equality (no alias family)
5190	    $exact = ($auth -eq 'endpoint')
5191	    $pinned = $(if ($ExpectModel) { $ExpectModel } else { [string](Get-PropertyValue $Turn 'Model' '') })
5192	    $forkOf = $(if ($mode -eq 'fork' -and $turnThread) { $turnThread } else { '' })
5193	    $expect = $ExpectThread
5194	    if (-not $expect -and $turnThread -and -not $forkOf) { $expect = $turnThread }
5195	    if (-not $expect -and -not $turnThread -and $newThread) { $expect = $newThread }
5196	    $resId = [string]$Events.Thread
5197	    $initId = [string]$Events.InitThread
5198	    $okId = { param([string]$Id) [bool]($Id -match $script:UuidRe -and (-not $expect -or $Id -eq $expect) -and (-not $forkOf -or $Id -ne $forkOf)) }
5199	    $candidateOf = { param([string]$Id) if ($Id -match $script:UuidRe -and (-not $forkOf -or $Id -ne $forkOf)) { $Id } else { '' } }
5200	    $o.Structured = [bool]$Events.HasStructured
5201	    $o.Reply = $(if ($Events.HasStructured) { [string]$Events.StructuredJson } elseif (-not $Events.IsError) { [string]$Events.Response } else { '' })
5202	    # (D6) the quota evidence: a rejecting rate_limit_event, else the limit wording of the result's
5203	    # text or stderr; its reset time (the event's, else a "|<unix time>" in the text) as ISO in the text
5204	    $errText = [string]$Events.Error
5205	    $quotaText = ''
5206	    $resetAt = $Events.RateLimitReset
5207	    if ($Events.RateLimitRejected) {
5208	        $quotaText = "usage limit reached (claude rate_limit_event $($Events.RateLimitStatus)$(if ($Events.RateLimitType) { ", $($Events.RateLimitType)" }))"
5209	    } elseif ($errText -and $errText -match $script:ClaudeQuotaRe) {
5210	        $quotaText = "usage limit: $(ConvertTo-OneLine $errText)"
5211	    } else {
5212	        $ql = @($lines | Where-Object { $_ -match $script:ClaudeQuotaRe }) | Select-Object -First 1
5213	        if ($ql) { $quotaText = "usage limit: $(ConvertTo-OneLine $ql)" }
5214	    }
5215	    if ($quotaText -and $null -eq $resetAt -and $errText -match '\|(?<t>[0-9]{10,13})\b') { $resetAt = ConvertFrom-ClaudeResetTime $Matches['t'] }
5216	    if ($quotaText -and $null -ne $resetAt) { $quotaText += "; resets at $(([DateTimeOffset]$resetAt).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', $script:Invariant))" }
5217	    $authText = ''
5218	    if (-not $quotaText) {
5219	        if ($errText -and $errText -match $script:ClaudeAuthRe) { $authText = ConvertTo-OneLine $errText }
5220	        else { $al = @($lines | Where-Object { $_ -match $script:ClaudeAuthRe }) | Select-Object -First 1; if ($al) { $authText = ConvertTo-OneLine $al } }
5221	    }
5222	    $evidenceClass = $(if ($quotaText) { 'quota' } elseif ($authText) { 'auth' } else { '' })
5223	    $fail = {
5224	        param([string]$Why, [string]$Class = '', [string[]]$Texts = @())
5225	        $o.Ok = $false
5226	        $o.Outcome = "failed: $Why"
5227	        $o.Class = $Class
5228	        $o.Texts = [string[]]@(@($Texts) + @($Why) | Where-Object { $_ })
5229	    }
5230	    $detail = $(if ($errText.Trim()) { $errText } else { $stderrTail })
5231	    if ($Pre) {
5232	        # (wave 29b, E12) a killed turn's init and model are judged too: a prohibited tool, an MCP
5233	        # server, another permission mode, apiKeySource, a missing capability field, another model -
5234	        # that problem is the reason (the stop is said after it), and no continuation may resume the
5235	        # session (ProofProblem); the salvage of the turn is still kept by the caller
5236	        $proofPre = Get-ClaudeInitProblem -Events $Events -Auth $auth
5237	        if (-not $proofPre.Problem) { $proofPre = Get-ClaudeServedModelProblem -Events $Events -Pinned $pinned -Exact:$exact }
5238	        if ($proofPre.Problem) {
5239	            $stopped = ConvertTo-OneLine ($Pre -replace '^failed:\s*', '')
5240	            & $fail "$($proofPre.Problem) (the turn was also stopped: $stopped)" $proofPre.Class @($quotaText, $errText, $stderrTail)
5241	            $o.ProofProblem = $proofPre.Problem
5242	            $o.ThreadCandidate = & $candidateOf $(if ($resId) { $resId } else { $initId })
5243	            return $o
5244	        }
5245	        $o.Outcome = $Pre
5246	        $o.Class = $(if ($quotaText) { 'quota' } else { '' })
5247	        $o.Texts = [string[]]@(@($quotaText, $errText, $stderrTail, ($Pre -replace '^failed:\s*', '')) | Where-Object { $_ })
5248	        $o.ThreadCandidate = & $candidateOf $(if ($resId) { $resId } else { $initId })
5249	        if ($o.ThreadCandidate -and $expect -and $o.ThreadCandidate -ne $expect) { $o.ThreadCandidate = '' }
5250	        # (D4) a killed turn's init already resolved the model: the continuation sends that id
5251	        $servedPre = [string]$Events.InitModel
5252	        if ($servedPre -and (-not $pinned -or (Test-ClaudeModelMatch -Pinned $pinned -Served $servedPre -Exact:$exact))) {
5253	            $o.ModelResolved = $servedPre
5254	            if ($pinned -match '(?i)\[1m\]$' -and $servedPre -notmatch '(?i)\[1m\]$') { $o.ModelResolved += '[1m]' }
5255	        }
5256	        return $o
5257	    }
5258	    $proof = Get-ClaudeInitProblem -Events $Events -Auth $auth
5259	    if ($proof.Problem) {
5260	        & $fail $proof.Problem $proof.Class
5261	        $o.ProofProblem = $proof.Problem
5262	        $o.ThreadCandidate = & $candidateOf $(if ($resId) { $resId } else { $initId })
5263	        return $o
5264	    }
5265	    if ($ExitCode -ne 0) {
5266	        & $fail "claude exit $ExitCode$(if ($detail) { " - $(ConvertTo-OneLine $detail)" })" $evidenceClass @($quotaText, $authText, $errText, $stderrTail)
5267	        if (& $okId $resId) { $o.Thread = $resId } else { $o.ThreadCandidate = & $candidateOf $(if ($resId) { $resId } else { $initId }) }
5268	        return $o
5269	    }
5270	    if ($Events.Malformed) {
5271	        & $fail "malformed event stream: $($Events.Malformed)" 'transport'
5272	        $o.ThreadCandidate = & $candidateOf $initId
5273	        return $o
5274	    }
5275	    if ([int]$Events.InitCount -le 0) {
5276	        & $fail "the claude event stream has no init event - the turn's tools, MCP servers and permission mode are not proven" 'permission'
5277	        return $o
5278	    }
5279	    if (-not $Events.HasResult) {
5280	        & $fail "no result event in the claude event stream$(if ($stderrTail) { " - $(ConvertTo-OneLine $stderrTail)" })" $evidenceClass @($quotaText, $authText, $stderrTail)
5281	        $o.ThreadCandidate = & $candidateOf $initId
5282	        return $o
5283	    }
5284	    if ($initId -and $resId -and $initId -ne $resId) {
5285	        & $fail "session id mismatch: init $initId, result $resId" 'unknown'
5286	        $o.ThreadCandidate = & $candidateOf $resId
5287	        return $o
5288	    }
5289	    if ($expect -and $resId -ne $expect) {
5290	        $why = $(if ($turnThread) { "parent session $expect not found, claude answered on $(if ($resId) { $resId } else { 'no session' })" } else { "the new session is $(if ($resId) { $resId } else { '(none)' }), not the minted $expect" })
5291	        & $fail $why 'unknown'
5292	        $o.ThreadCandidate = & $candidateOf $resId
5293	        return $o
5294	    }
5295	    if ($forkOf -and $resId -eq $forkOf) {
5296	        & $fail "the fork came back on its parent session $forkOf (--fork-session started no new session)" 'unknown'
5297	        return $o
5298	    }
5299	    if (-not ($resId -match $script:UuidRe)) {
5300	        & $fail "the result's session_id '$resId' is not a uuid" 'unknown'
5301	        return $o
5302	    }
5303	    if ($Events.IsError -or $Events.Subtype -ne 'success') {
5304	        $st = $(if ($Events.Subtype) { $Events.Subtype } else { '(none)' })
5305	        $cls = $evidenceClass
5306	        if (-not $cls -and $st -eq 'error_max_turns') { $cls = 'capability' }
5307	        if (-not $cls -and $st -eq 'error_max_structured_output_retries') { $cls = 'capability' }
5308	        $what = $(if ($st -eq 'error_max_turns') { 'max turns reached (--max-turns)' } elseif ($st -eq 'error_max_structured_output_retries') { 'no reply satisfied the schema (structured output retries exhausted)' } else { '' })
5309	        & $fail "claude $st$(if ($what) { " - $what" })$(if ($detail) { " - $(ConvertTo-OneLine $detail)" })" $cls @($quotaText, $authText, $errText, $stderrTail)
5310	        $o.Thread = $resId
5311	        return $o
5312	    }
5313	    # (D4) one resolved model per thread, proven per turn
5314	    $served = [string]$Events.InitModel
5315	    if (-not $served) {
5316	        & $fail "the init event names no model (asked $pinned)" 'unknown'
5317	        $o.ThreadCandidate = $resId
5318	        return $o
5319	    }
5320	    # (D4) the init model against the pin; (wave 29b, E13) every assistant message by the init's id
5321	    $modelProof = Get-ClaudeServedModelProblem -Events $Events -Pinned $pinned -Exact:$exact
5322	    if ($modelProof.Problem) {
5323	        & $fail $modelProof.Problem $modelProof.Class
