6315	# ----------------------------------------------------------------------------- machine-wide endpoint health (wave 26b, D13 - ROADMAP R20)
6316	#
6317	# ONE file per machine, <codex home>/codex-consult-health.json (CODEX_CONSULT_HEALTH=<path> names
6318	# another; CODEX_CONSULT_HEALTH=none: no file - read nor written), so that the repositories of
6319	# one machine see each other's endpoint outcomes and running members:
6320	#   { "health_version": 1,
6321	#     "endpoints": [ { "endpoint": "<provider fingerprint>", "class": "ok" | "<a provider failure
6322	#                      class>", "kind": "burst" | "", "until": "<iso>" | null, "retry_after": "<the
6323	#                      reset time the provider named>" | null, "repo": "<repository root>", "when":
6324	#                      "<iso>", "message": "<the failure's message, cut to 200>"[, "quota_mark": {
6325	#                      "class": "quota", "kind", "until", "retry_after", "message", "when" } - (wave
6326	#                      29b, E15) on an "ok" record whose turn saw a rejecting rate-limit event] } ],
6327	#     "running":   [ { "endpoint": "<fingerprint>", "label": "<provider label>", "pid": <the run's
6328	#                      bridge pid>, "start_time": "<its start>", "repo": "...", "task": "...", "nn":
6329	#                      "<NN>", "panel": "<panel id or ''>", "since": "<iso>"[, "plan": "<the roster
6330	#                      entry's plan> - (wave 29b, E16) only when the entry names one"] } ] }
6331	# Written under <file>.lock (exclusive open, retried up to 10 s; not acquired = not written) by
6332	# every run that records a provider failure (class operator excepted) or a usable reply
6333	# (Add-MachineHealthRecord: until = a quota's reset time, else the hit + 60 min (10 for a burst);
6334	# an auth failure + 24 h; else null), and by every run while its engine turns run
6335	# (Register-MachineRunning / Unregister-MachineRunning). Every write prunes: an endpoint record
6336	# older than 24 h whose until has passed; a running row whose pid + start time is gone. Read by
6337	# every endpoint-health question (Get-EndpointHealth: every roster walk, the panel selection,
6338	# codex-providers.ps1) and by the panel's scheduler (Get-MachineRunningCount: the endpoint
