6640	function Add-MachineHealthRecord {
6641	    param([string]$Fingerprint, [string]$Outcome, $Failure = $null, [string]$Repo = '', [int]$Attempts = 3, [double]$AttemptSec = 0, $Record = $null, $QuotaMark = $null)
6642	    # (wave 26c, D2) a record that is not written for another reason is no lock timeout
6643	    $script:MachineHealthLastError = ''
6644	    if (-not $Fingerprint -or -not (Get-MachineHealthPath)) { return $false }
6645	    # (wave 28b, D13) the caller's record (the one it journaled), else built here
6646	    $rec = $(if ($null -ne $Record) { $Record } else { New-MachineHealthRecord -Fingerprint $Fingerprint -Outcome $Outcome -Failure $Failure -Repo $Repo -QuotaMark $QuotaMark })
6647	    if ($null -eq $rec) { return $false }
6648	    return (Update-MachineHealth -AddEndpoint $rec -Attempts $Attempts -AttemptSec $AttemptSec)
6649	}
6650	
6651	# (wave 28b, D13) The endpoint record of a run's outcome (see Add-MachineHealthRecord), or $null when
6652	# there is none (no fingerprint, class operator, neither usable nor a provider failure). Its `when`
6653	# is fixed here, so the journaled record and the retried one are the same record. (wave 29b, E15)
6654	# -QuotaMark (engine_run.quota_mark of a usable reply): the ok record carries it as quota_mark {class
6655	# quota, kind, until (its reset, else its time + 60 min, 10 for a burst), retry_after, message, when}.
6656	function New-MachineHealthRecord {
6657	    param([string]$Fingerprint, [string]$Outcome, $Failure = $null, [string]$Repo = '', $QuotaMark = $null)
6658	    if (-not $Fingerprint) { return $null }
6659	    $now = [DateTimeOffset]::Now
6660	    $rec = $null
6661	    if (Test-UsableOutcome $Outcome) {
6662	        $rec = [pscustomobject]@{ endpoint = $Fingerprint; class = 'ok'; kind = ''; until = $null; retry_after = $null; repo = $Repo; when = (Format-OffsetIso $now); message = '' }
6663	        if ($null -ne $QuotaMark -and [string](Get-PropertyValue $QuotaMark 'class' '') -eq 'quota') {
6664	            $mWhen = ConvertTo-WhenOffset (Get-PropertyValue $QuotaMark 'when' '')
6665	            if ($null -eq $mWhen) { $mWhen = $now }
6666	            $mKind = [string](Get-PropertyValue $QuotaMark 'kind' '')
6667	            $mRa = ConvertTo-WhenOffset (Get-PropertyValue $QuotaMark 'retry_after' '')
6668	            $mUntil = $(if ($null -ne $mRa) { $mRa } else { $mWhen.AddMinutes($(if ($mKind -eq 'burst') { $script:BurstOutMinutes } else { $script:QuotaOutMinutes })) })
6669	            $mMsg = [string](Get-PropertyValue $QuotaMark 'message' '')
6670	            if ($mMsg.Length -gt 200) { $mMsg = $mMsg.Substring(0, 200) }
6671	            $rec | Add-Member -NotePropertyName 'quota_mark' -NotePropertyValue ([pscustomobject]@{ class = 'quota'; kind = $mKind; until = (Format-OffsetIso $mUntil); retry_after = $(if ($null -ne $mRa) { Format-OffsetIso $mRa } else { $null }); message = $mMsg; when = (Format-OffsetIso $mWhen) })
6672	        }
6673	    } elseif ($null -ne $Failure) {
6674	        $cls = [string](Get-PropertyValue $Failure 'class' '')
6675	        if (-not $cls -or $cls -eq 'operator') { return $null }
6676	        $when = ConvertTo-WhenOffset (Get-PropertyValue $Failure 'when' '')
6677	        if ($null -eq $when) { $when = $now }
6678	        $kind = [string](Get-PropertyValue $Failure 'kind' '')
6679	        $until = $null
6680	        $ra = $null
6681	        if ($cls -eq 'quota') {
6682	            $ra = ConvertTo-WhenOffset (Get-PropertyValue $Failure 'retry_after' '')
6683	            if ($null -ne $ra) { $until = $ra } else { $until = $when.AddMinutes($(if ($kind -eq 'burst') { $script:BurstOutMinutes } else { $script:QuotaOutMinutes })) }
6684	        } elseif ($cls -eq 'auth') { $until = $when.AddHours(24) }
6685	        $msg = [string](Get-PropertyValue $Failure 'message' '')
6686	        if ($msg.Length -gt 200) { $msg = $msg.Substring(0, 200) }
6687	        $rec = [pscustomobject]@{ endpoint = $Fingerprint; class = $cls; kind = $kind; until = $(if ($null -ne $until) { Format-OffsetIso $until } else { $null }); retry_after = $(if ($null -ne $ra) { Format-OffsetIso $ra } else { $null }); repo = $Repo; when = (Format-OffsetIso $when); message = $msg }
6688	    }
6689	    return $rec
6690	}
6691	
6692	# This run's row in running[] while its engine turns run (the bridge's pid and start time).
6693	# (wave 29b, E16) -Plan: the roster entry's plan - the row carries it when there is one, so a panel
6694	# elsewhere counts this run against the plan's limit too (Get-MachineRunningCount -Plans).
6695	function Register-MachineRunning {
6696	    param([string]$Fingerprint, [string]$Label = '', [string]$Repo = '', [string]$Task = '', [string]$Nn = '', [string]$Panel = '', [string]$Plan = '')
6697	    if (-not $Fingerprint -or -not (Get-MachineHealthPath)) { return $false }
6698	    $row = [pscustomobject]@{ endpoint = $Fingerprint; label = $Label; pid = $PID; start_time = [string](Get-ProcessStartIso -ProcessId $PID); repo = $Repo; task = $Task; nn = $Nn; panel = $Panel; since = (Get-IsoTimestamp) }
6699	    if ($Plan) { $row | Add-Member -NotePropertyName 'plan' -NotePropertyValue $Plan }
6700	    return (Update-MachineHealth -AddRunning $row -RemovePid $PID)
6701	}
6702	
6703	function Unregister-MachineRunning {
6704	    if (-not (Get-MachineHealthPath)) { return $false }
6705	    if (@((Read-MachineHealth -Fresh).Running | Where-Object { [int](Get-PropertyValue $_ 'pid' 0) -eq $PID }).Count -eq 0) { return $true }
6706	    return (Update-MachineHealth -RemovePid $PID)
6707	}
6708	
6709	# How many runs of the machine are running on these endpoints outside the panel $ExcludePanel
6710	# (another repository's members, another panel, a single run) - live rows only. (wave 29b, E16)
6711	# -Plans: a row of one of these plans counts too, whatever its endpoint, engine and repository (a
6712	# codex ZAI run of plan zai for a claude ZAI-claude member). { Count; Rows; ByPlan (the rows that
6713	# count only through their plan) }.
6714	function Get-MachineRunningCount {
6715	    param([string[]]$Fingerprints, [string]$ExcludePanel = '', [string[]]$Plans = @())
6716	    $planSet = @(@($Plans) | Where-Object { $_ })
6717	    $rows = @((Read-MachineHealth).Running | Where-Object {
6718	            $fp = [string](Get-PropertyValue $_ 'endpoint' '')
6719	            $rp = [string](Get-PropertyValue $_ 'plan' '')
6720	            (($fp -and @($Fingerprints) -contains $fp) -or ($rp -and $planSet -ccontains $rp)) -and -not ($ExcludePanel -and [string](Get-PropertyValue $_ 'panel' '') -eq $ExcludePanel) -and
6721	            (Test-PidAlive -ProcessId ([int](Get-PropertyValue $_ 'pid' 0)) -StartTime (ConvertTo-StartIso (Get-PropertyValue $_ 'start_time' '')))
6722	        })
6723	    $byPlan = @($rows | Where-Object { -not (@($Fingerprints) -contains [string](Get-PropertyValue $_ 'endpoint' '')) })
6724	    return [pscustomobject]@{ Count = $rows.Count; Rows = [object[]]$rows; ByPlan = [object[]]$byPlan }
6725	}
6726	
6727	# ----------------------------------------------------------------------------- reviewer roster
6728	#
6729	# The reviewer roster is an ordered list of reviewers the operator is willing to use, first
6730	# choice first. A JSON file (never created by the bridge):
6731	#   CODEX_CONSULT_ROSTER=<path>   that file; it MUST exist (a roster that is asked for and
6732	#                                 missing refuses the run - it is never skipped silently)
6733	#   CODEX_CONSULT_ROSTER=none     no roster at all, the default file is ignored too
6734	#   unset                         <codex home>/codex-consult-roster.json when it exists;
6735	#                                 absent = no roster: everything behaves as without one
6736	#
6737	#   { "roster_version": 1,
6738	#     "reviewers": [ { "provider": "openai", "model": "gpt-5.1" },
6739	#                    { "provider": "ZAI", "model": "glm-5.3" },
6740	#                    { "provider": "local", "model": "m", "auth": "none",
6741	#                      "codex_config": ["model_catalog_json=~/.codex/catalog.json"] } ] }
6742	#
6743	#   provider      required: a [model_providers.<name>] table of the Codex config
6744	#                 (case-sensitive) or openai
6745	#   model         optional: absent = the model resolves as without a roster (the Codex
6746	#                 config's top-level model)
6747	#   codex_config  optional: key=value items with exactly the -CodexConfig rules
6748	#                 (ConvertFrom-CodexConfigItems)
6749	#   auth          optional, only "none": the endpoint needs no credential (a table without
6750	#                 env_key/bearer token then passes the credential check; a table WITH
6751	#                 env_key still needs the variable). (wave 29) Engine claude: "subscription"
6752	#                 (the default - the claude.ai login) or "api-key" (ANTHROPIC_API_KEY)
6753	#   panel         optional, "always" (the default) or "weighty": with -Panel a weighty
6754	#                 reviewer joins only on the weighty purposes (framing, decision,
6755	#                 core-contract, acceptance, stuck) or with -PanelAll. The single-reviewer
6756	#                 walk ignores it.
